def fixed_material_exploration_input(*, candidates: tuple[CanonicalRecord, ...], history: CanonicalRecord,
                                     wave_index: int, budget_operands: tuple[int, ...]) -> MaterialExplorationScientificInput:
    if budget_operands != (2, 4, 8, 1, 1):
        raise ValueError("constructive-search budget differs from the complete original numeric export")
    key = (sha256(canonical_json_bytes(candidates)).hexdigest(), history.fingerprint(), wave_index)
    if key not in _FIXED_RANK_INPUTS:
        raise ValueError("unknown material graph/history requires an authenticated complete original rank census and current target binding")
    original_candidates_sha256, original_history_sha256, ranks = _FIXED_RANK_INPUTS[key]
    return MaterialExplorationScientificInput(
        current_candidates_sha256=key[0], current_history_sha256=key[1],
        original_candidates_sha256=original_candidates_sha256, original_history_sha256=original_history_sha256,
        wave_index=wave_index, budget_operands=budget_operands,
        action_ranks=tuple(MaterialExplorationActionRank(*row) for row in ranks),
        original_source=_ORIGINAL_SOURCE, export_receipt=_EXPORT_RECEIPT,
    )
